        torch.backends.cuda.matmul.allow_tf32 = old_tf32

    if output.shape[0] == 1:
        return output
    return output.tril_()


def _high_batch_1024_cholesky(
    data: torch.Tensor, output: torch.Tensor
) -> torch.Tensor:
    global _batch_half_panel, _batch_trsm_pointers
    global _batch_factor_workspace, _batch_factor_info
    _ext.batch_lower_copy_cuda(data, output)
    n = output.shape[-1]
    block = 256
    half_shape = (output.shape[0], n - block, block)
    if _batch_half_panel is None or _batch_half_panel.shape != half_shape:
        _batch_half_panel = torch.empty(
            half_shape, device=output.device, dtype=torch.float16
        )
    pointer_count = 2 * output.shape[0]
    if (
        _batch_trsm_pointers is None
        or _batch_trsm_pointers.numel() != pointer_count
    ):
        _batch_trsm_pointers = torch.empty(
            pointer_count, device=output.device, dtype=torch.int64
        )

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for k in range(0, n, block):
            stop = k + block
            diagonal = output[:, k:stop, k:stop]
            factor = torch.linalg.cholesky_ex(
                diagonal,
                check_errors=False,
                out=(_batch_factor_workspace, _batch_factor_info),
            ).L
            panel = output[:, stop:, k:stop]
            if stop == n:
                _ext.prepare_batch_factor_and_pointers_cuda(
                    factor, diagonal, panel, _batch_trsm_pointers
